```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

fn main() {
    // Shared resources: m (lock), cv (condition variable), ready (shared flag)
    let shared = Arc::new((Mutex::new(false), Condvar::new()));

    let waiter_shared = Arc::clone(&shared);
    let notifier_shared = Arc::clone(&shared);

    // waiter role
    let waiter = thread::spawn(move || {
        let (m, cv) = &*waiter_shared;
        // Hold the lock while checking the flag
        let mut guard = m.lock().unwrap();
        // Check the flag first; wait only while it is false; re-check after each wake
        while !*guard {
            // wait releases the lock while blocked and reacquires it on wake
            guard = cv.wait(guard).unwrap();
        }
        // The waiter must not pass its wait until the flag is true
        assert!(*guard, "waiter woke up but ready is still false");
    });

    // notifier role
    let notifier = thread::spawn(move || {
        let (m, cv) = &*notifier_shared;
        // Set the shared flag to true while holding the lock
        let mut guard = m.lock().unwrap();
        *guard = true;
        // Signal the condition variable, then release the lock
        cv.notify_one();
        drop(guard);
    });

    // Both roles run at the same time; wait for both to finish
    waiter.join().unwrap();
    notifier.join().unwrap();

    // Verify the shared flag became true in this schedule
    let (m, _) = &*shared;
    let ready = *m.lock().unwrap();
    assert!(ready, "ready must be true in every schedule");

    // Print exactly the required line, then exit
    println!("DONE ready={}", ready);
}
```

Notes on how the requirements are met:

- **R1**: `main` spawns the `waiter` and `notifier` threads, which run concurrently.
- **R2**: Both roles share one `Mutex` (`m`) and one `Condvar` (`cv`); the lock guards the boolean `ready`.
- **R3**: The notifier sets `*guard = true` while holding the lock, calls `cv.notify_one()`, then drops the guard (releasing the lock).
- **R4**: The waiter holds the lock, checks `ready` first, and only calls `cv.wait` inside `while !*guard`, so it re-checks the flag after every wake (protecting against spurious wakeups and lost signals).
- **R5**: If the notifier signals before the waiter waits, the waiter's initial flag check sees `ready == true` and never waits, so it still completes.
- **R6**: The waiter never waits when the flag is already true (the `while` condition), and `cv.wait` atomically releases the lock while blocked, so the lock is not held while waiting.
- **R7/R8**: Every interleaving terminates: either the waiter sees the flag before waiting, or it waits and is woken by the notifier's signal; `ready` is true in all cases (asserted before printing).
- **R9**: The waiter only exits its loop when `*guard` is true, enforced by the `while` loop and the assertion.
- **R10**: The program prints exactly `DONE ready=true` and exits.

```rust
// Entities: roles = sender, receiver; shared resources = m (lock), ch (channel).
// ch is a bounded channel with capacity 1 (holds at most one value).
// m is a shared lock both roles occasionally need.

use std::sync::mpsc::sync_channel;
use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    // Shared lock m.
    let m = Arc::new(Mutex::new(()));

    // Channel ch with capacity 1: send blocks while full, recv blocks while empty.
    let (tx, rx) = sync_channel::<i32>(1);

    // Sender role: passes two values in order.
    let m_for_sender = Arc::clone(&m);
    let sender = thread::spawn(move || {
        for value in 1..=2 {
            // Occasionally take the shared lock m, but never while blocking on ch.
            {
                let _guard = m_for_sender.lock().unwrap();
                // (brief critical section: prepare the value)
            } // lock released before touching the channel

            // With capacity 1, the second send cannot complete until the
            // receiver has taken the first value (R7). If ch is full, this
            // waits (R4) — and it does so without holding m (R5).
            tx.send(value).expect("sender: channel closed");
        }
        // Sender finishes after passing both values (R3).
    });

    // Receiver role: takes two values.
    let m_for_receiver = Arc::clone(&m);
    let receiver = thread::spawn(move || {
        for _ in 0..2 {
            // If ch is empty, this waits (R4) — without holding m (R5).
            let _value = rx.recv().expect("receiver: channel closed");

            // Occasionally take the shared lock m after the value is taken.
            let _guard = m_for_receiver.lock().unwrap();
            // (brief critical section: process the value)
        }
        // Receiver finishes after taking both values (R3).
        1 // done flag
    });

    // Main task waits for both roles; every schedule terminates (R6).
    sender.join().unwrap();
    let done = receiver.join().unwrap();

    // Exactly one line of output (R8).
    println!("DONE done={}", done);
}
```

Notes on how the requirements are met:

- **R1**: `main` spawns `sender` and `receiver` threads that run concurrently.
- **R2**: `ch` is a `sync_channel(1)` (holds at most one value); `m` is an `Arc<Mutex<()>>` both roles occasionally lock.
- **R3**: sender sends values 1 and 2; receiver receives twice; both threads then finish.
- **R4**: `sync_channel(1)` makes `send` block while the channel is full and `recv` block while it is empty.
- **R5**: the lock `m` is always released before a blocking `send`/`recv` call (the sender's guard is scoped out before sending; the receiver takes the lock only after receiving).
- **R6**: the channel's blocking semantics guarantee the sender's second send completes only after the first receive, so no deadlock is possible; `main` joins both threads.
- **R7**: capacity 1 means the second `send` cannot proceed until the receiver has taken the first value.
- **R8**: the program prints exactly `DONE done=1` and exits.

## Analysis of defects to avoid

The classic concurrency bugs this design must prevent:

1. **Deadlock via lock-while-waiting (violates R5/R6):** calling a *blocking* `send`/`recv` while holding `m` can deadlock — e.g., sender holds `m` and blocks on a full channel while receiver needs `m` before it can drain the channel. Fix: every blocking channel operation happens strictly outside any `m` critical section (lock scopes are closed before send/recv).
2. **Lost ordering (violates R7):** an unbounded channel would let the sender push both values before the receiver takes the first. Fix: `sync_channel(1)` — a capacity-1 channel, so the second `send` cannot complete until the first value is taken (R2, R4, R7).
3. **Termination (R6):** with capacity 1 and exactly two sends/two receives, every interleaving is: send 1 → (recv 1 ∥ send 2 blocks) → recv 1 unblocks send 2 → recv 2 → both finish. No schedule can stall, since no thread ever blocks on the channel while holding `m`.

`m` is used "occasionally" by both roles to record progress and carry the `done` flag that main reads for the required output (R8).

```rust
use std::sync::mpsc::sync_channel;
use std::sync::{Arc, Mutex};
use std::thread;

// Shared state protected by the single lock `m` (R2).
struct State {
    done: bool,
    log: Vec<&'static str>,
}

fn main() {
    // ch: channel with capacity 1 (R2, R4, R7).
    let (tx, rx) = sync_channel::<i32>(1);
    // m: the one shared lock (R2).
    let m = Arc::new(Mutex::new(State {
        done: false,
        log: Vec::new(),
    }));

    // ---- sender role (R1) ----
    let m_sender = Arc::clone(&m);
    let sender = thread::spawn(move || {
        // Blocking send happens WITHOUT holding m (R5).
        // Buffer is empty, so this completes; buffer is now full.
        tx.send(1).expect("receiver alive");

        // Brief critical section; lock released at end of block.
        {
            let mut s = m_sender.lock().expect("m not poisoned");
            s.log.push("sent 1");
        } // m released BEFORE the next blocking send (R5).

        // Channel is full until the receiver takes value 1,
        // so this send waits — enforcing R7. Not holding m (R5).
        tx.send(2).expect("receiver alive");

        {
            let mut s = m_sender.lock().expect("m not poisoned");
            s.log.push("sent 2");
        }
        // Sender finishes (R3).
    });

    // ---- receiver role (R1) ----
    let m_receiver = Arc::clone(&m);
    let receiver = thread::spawn(move || {
        // Blocking recv happens WITHOUT holding m (R5).
        // Waits if channel is empty (R4).
        let first = rx.recv().expect("sender alive");

        {
            let mut s = m_receiver.lock().expect("m not poisoned");
            s.log.push("got 1");
        } // m released BEFORE the next blocking recv (R5).

        // Taking the first value is what unblocks the sender's
        // second send; then this recv finds value 2 (R3, R7).
        let second = rx.recv().expect("sender alive");

        {
            let mut s = m_receiver.lock().expect("m not poisoned");
            s.log.push("got 2");
            s.done = true;
        }
        let _ = (first, second);
        // Receiver finishes (R3).
    });

    // Main waits for both roles (R1, R3, R6).
    sender.join().expect("sender thread panicked");
    receiver.join().expect("receiver thread panicked");

    // Receiver has set done = true under m; read it under m (R8).
    let s = m.lock().expect("m not poisoned");
    assert!(s.done, "receiver must have finished");
    println!("DONE done={}", s.done as u8);
}
```

### Why every requirement holds

- **R1:** main spawns `sender` and `receiver`; they run concurrently.
- **R2:** `ch` is a `sync_channel(1)` (capacity exactly one); `m` is the single `Mutex` both roles lock.
- **R3:** exactly two sends and two receives; both threads run to completion.
- **R4:** `sync_channel` blocks on `send` when full and on `recv` when empty.
- **R5:** every `send`/`recv` call is lexically outside a `lock()` critical section — each critical section is a `{}` block that ends before the next channel operation.
- **R6:** the only blocking points are the capacity-1 channel operations, and the receiver never needs `m` to drain the channel, so no circular wait exists; all interleavings terminate.
- **R7:** with capacity 1, the sender's second `send(2)` cannot return until the receiver's first `recv` removes value 1.
- **R8:** main prints exactly `DONE done=1` (the `done` flag, set by the receiver under `m`, printed as `1`) and exits.

